package render

import (
	"encoding/json"
	"os"
	"testing"
)

// goldenCase holds the output of the WordPress originals for one input,
// generated by dev/golden/gen.php (make golden).
type goldenCase struct {
	Name      string `json:"name"`
	In        string `json:"in"`
	Autop     string `json:"autop"`
	Unautop   string `json:"unautop"`
	Texturize string `json:"texturize"`
	Smilies   string `json:"smilies"`
	Dangit    string `json:"dangit"`
	Excerpt   string `json:"excerpt"`
}

// wpShortcodes are the shortcodes registered in the reference WordPress.
var wpShortcodes = map[string]bool{
	"wp_caption": true, "caption": true, "gallery": true, "playlist": true, "audio": true,
	"video": true, "embed": true, "fotogalerie": true, "paypal-donation": true,
}

func loadGolden(t *testing.T) []goldenCase {
	t.Helper()
	raw, err := os.ReadFile("testdata/golden.json")
	if err != nil {
		t.Fatal(err)
	}
	var cases []goldenCase
	if err := json.Unmarshal(raw, &cases); err != nil {
		t.Fatal(err)
	}
	return cases
}

func runGolden(t *testing.T, field string, fn func(goldenCase) (got, want string)) {
	t.Helper()
	failed := 0
	for _, c := range loadGolden(t) {
		got, want := fn(c)
		if got != want {
			failed++
			if failed <= 5 {
				t.Errorf("%s %s mismatch\n--- got\n%q\n--- want\n%q", field, c.Name, got, want)
			}
		}
	}
	if failed > 0 {
		t.Errorf("%s: %d cases differ", field, failed)
	}
}

func TestGoldenAutop(t *testing.T) {
	runGolden(t, "autop", func(c goldenCase) (string, string) { return Autop(c.In), c.Autop })
}

func TestGoldenShortcodeUnautop(t *testing.T) {
	runGolden(t, "unautop", func(c goldenCase) (string, string) {
		return ShortcodeUnautop(Autop(c.In), wpShortcodes), c.Unautop
	})
}
